import React, { useState } from 'react';
import { Link } from 'react-router-dom';

function EmotionRecommendPage({ movies = [] }) {
  const [inputText, setInputText] = useState('');
  const [selectedEmotion, setSelectedEmotion] = useState(null);
  const [recommendedMovie, setRecommendedMovie] = useState(null);
  const [loading, setLoading] = useState(false);

  const emotionOptions = [
    { id: 'comfort', label: '나는 오늘 위로가 필요해' },
    { id: 'laugh', label: '나는 오늘 웃음이 필요해' },
    { id: 'thrill', label: '나는 오늘 짜릿한 자극이 필요해' },
    { id: 'romance', label: '나는 오늘 설렘이 필요해' }
  ];

  // 💡 사용자의 감정 텍스트를 분석하여 연관된 TMDB 장르 ID를 반환
  const analyzeEmotion = (text) => {
    if (!text) return [];
    const t = text.toLowerCase();
    if (t.includes('위로') || t.includes('우울') || t.includes('슬픔') || t.includes('힘들') || t.includes('눈물') || t.includes('지침')) return [18, 10751]; // 드라마, 가족
    if (t.includes('웃음') || t.includes('코미디') || t.includes('재밌') || t.includes('즐거') || t.includes('유쾌')) return [35, 16]; // 코미디, 애니
    if (t.includes('짜릿') || t.includes('액션') || t.includes('스트레스') || t.includes('스릴') || t.includes('답답')) return [28, 53, 27]; // 액션, 스릴러, 공포
    if (t.includes('설렘') || t.includes('사랑') || t.includes('로맨스') || t.includes('달달')) return [10749]; // 로맨스
    return []; // 기본값
  };

  // 💡 데이터 및 후기 기반 추천 로직 (랜덤성 부여)
  const handleRecommend = (emotionText) => {
    if (!emotionText.trim()) {
      alert('오늘의 기분이나 감정을 조금만 적어주세요!');
      return;
    }
    
    setSelectedEmotion(emotionText);
    setLoading(true);
    setRecommendedMovie(null);

    setTimeout(() => {
      let chosen = null;
      let targetGenres = analyzeEmotion(emotionText);
      let reasonData = "";
      let mockReview = "";

      if (movies && movies.length > 0) {
        // 영화별로 감정 매칭 점수를 계산
        let scoredMovies = movies.map(m => {
          let score = 0;
          // 1. 장르가 일치하면 아주 큰 가산점 부여
          if (m.genre_ids && targetGenres.length > 0) {
            const matchCount = m.genre_ids.filter(id => targetGenres.includes(id)).length;
            score += matchCount * 50; 
          }
          // 2. 기본 평점 반영
          score += (m.vote_average || 0); 
          
          // 3. 💡 매번 똑같은 영화만 뜨지 않도록 랜덤 점수(0~15점) 추가
          score += Math.random() * 15; 
          
          return { ...m, matchScore: score };
        });

        // 점수 순으로 내림차순 정렬
        scoredMovies.sort((a, b) => b.matchScore - a.matchScore);
        
        // 최상위 점수 영화 1개 선택
        chosen = scoredMovies[0];

        if (chosen) {
          const rating = (chosen.vote_average || 0).toFixed(1);
          const isMatched = targetGenres.length > 0 && chosen.matchScore > 20;
          
          reasonData = isMatched 
            ? `입력하신 감정 키워드와 완벽히 일치하는 장르 특성을 가졌으며, 실관람객 평점 ${rating}점을 기록한 검증된 작품입니다.` 
            : `현재 상영작 중 누적 평점 ${rating}점으로 대중에게 가장 호평받고 있는 작품으로, 기분 전환을 확실히 도와드릴게요.`;

          // 감정에 따른 가상의 실관람객 후기 매칭
          mockReview = targetGenres.includes(35) ? `"보는 내내 웃음이 끊이지 않았어요! 스트레스가 다 날아가는 기분!"` :
                       targetGenres.includes(10749) ? `"설레는 분위기와 영상미가 너무 예뻐서 마음이 몽글몽글해졌습니다."` :
                       targetGenres.includes(28) ? `"눈을 뗄 수 없는 시원한 전개와 액션 타격감이 최고입니다."` :
                       targetGenres.includes(18) ? `"마음에 깊은 여운과 위로를 남기는 훌륭한 스토리였습니다. 강력 추천해요."` :
                       `"시간 가는 줄 모르고 푹 빠져서 봤습니다. 후회 없는 선택!"`;
        }
      }

      // API 데이터가 아예 전달되지 않았을 경우의 예외 처리
      if (!chosen) {
        chosen = {
          title: '현재 불러올 수 있는 상영작이 없습니다',
          overview: '메인 화면에서 영화 데이터를 성공적으로 불러왔는지 확인해 주세요.',
          poster_path: null
        };
        reasonData = "데이터 연결 지연";
        mockReview = "영화 정보를 가져오는 중입니다.";
      }

      chosen.reasonData = reasonData;
      chosen.mockReview = mockReview;

      setRecommendedMovie(chosen);
      setLoading(false);
    }, 800);
  };

  return (
    <div 
      className="w-full min-h-screen py-16 px-6 flex flex-col items-center justify-center relative bg-gradient-to-br from-purple-100 to-white" 
      style={{ fontFamily: 'Pretendard, sans-serif' }}
    >
      <div className="w-full max-w-3xl relative overflow-hidden bg-white/40 backdrop-blur-2xl border border-white/60 shadow-[0_8px_32px_0_rgba(80,51,150,0.08)] rounded-[40px] p-8 md:p-10 space-y-8">
        
        <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-white/40 to-transparent pointer-events-none"></div>

        {/* 상단 타이틀 영역 */}
        <div className="text-center space-y-3 relative z-10">
          <span className="inline-block text-[11px] font-black tracking-widest text-[#503396] uppercase bg-white/60 backdrop-blur-md px-4 py-1.5 rounded-full border border-white shadow-sm">
            MEGABOX EMOTION CARE
          </span>
          <h2 className="text-3xl md:text-4xl font-black text-zinc-900 tracking-tight">
            오늘의 감정에 맞는 영화를 골라드려요
          </h2>
          <p className="text-xs text-zinc-600 font-medium">
            오늘 당신의 마음을 자유롭게 들려주세요. 당신의 감정을 따뜻하게 보살펴 줄 영화를 찾아드릴게요.
          </p>
        </div>

        {/* 직접 감정을 적을 수 있는 입력창 */}
        <div className="relative z-10 w-full">
          <form 
            onSubmit={(e) => { e.preventDefault(); handleRecommend(inputText); }} 
            className="flex items-center bg-white/60 backdrop-blur-md border border-white/80 rounded-2xl shadow-sm p-2 focus-within:shadow-md focus-within:border-purple-300 transition-all"
          >
            <input 
              type="text" 
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder="오늘 하루는 어떠셨나요? (예: 일 때문에 너무 스트레스 받아)" 
              className="flex-grow bg-transparent px-4 py-2 text-sm text-zinc-800 placeholder-zinc-400 focus:outline-none font-medium"
            />
            <button 
              type="submit" 
              className="px-6 py-3 bg-[#503396] hover:bg-[#3b2570] text-white font-black text-xs rounded-xl transition shadow-md shrink-0"
            >
              분석 및 추천
            </button>
          </form>
        </div>

        {/* 구분선 */}
        <div className="flex items-center gap-4 relative z-10 opacity-60 my-2">
          <div className="flex-1 h-px bg-zinc-300"></div>
          <span className="text-[11px] text-zinc-500 font-bold">또는 아래에서 선택해보세요</span>
          <div className="flex-1 h-px bg-zinc-300"></div>
        </div>

        {/* 투명한 유리 질감의 선택 버튼 (중앙 정렬, 이모지 없음) */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 relative z-10">
          {emotionOptions.map((option) => (
            <button
              key={option.id}
              onClick={() => {
                setInputText(''); // 버튼 클릭 시 입력창 초기화
                handleRecommend(option.label);
              }}
              className={`p-4 rounded-2xl text-center font-black text-sm transition-all duration-300 backdrop-blur-xl border ${
                selectedEmotion === option.label
                  ? 'bg-[#503396]/70 text-white border-white/40 shadow-[0_8px_20px_rgba(80,51,150,0.25)] scale-[1.02]' 
                  : 'bg-white/30 hover:bg-white/50 text-zinc-700 border-white/50 shadow-sm hover:shadow-md'
              }`}
            >
              {option.label}
            </button>
          ))}
        </div>

        {/* 로딩 상태 */}
        {loading && (
          <div className="text-center py-10 text-[#503396] font-bold animate-pulse text-sm relative z-10">
            데이터와 후기를 분석하여 어울리는 영화를 찾는 중입니다...
          </div>
        )}

        {/* 추천 결과 카드 */}
        {recommendedMovie && !loading && (
          <div className="bg-white/60 backdrop-blur-2xl border border-white/80 rounded-3xl p-8 shadow-xl flex flex-col md:flex-row items-start gap-8 animate-fade-in relative z-10 mt-4">
            
            {/* 포스터 영역 */}
            <div className="w-40 h-56 rounded-2xl bg-zinc-200 overflow-hidden shadow-lg shrink-0 border border-white flex items-center justify-center relative">
              {recommendedMovie.poster_path || recommendedMovie.backdrop_path ? (
                <img 
                  src={`https://image.tmdb.org/t/p/w500${recommendedMovie.poster_path || recommendedMovie.backdrop_path}`} 
                  alt={recommendedMovie.title} 
                  className="w-full h-full object-cover" 
                />
              ) : (
                <span className="text-xs text-zinc-400 font-bold">포스터 없음</span>
              )}
            </div>

            {/* 컨텐츠 및 설명 영역 */}
            <div className="flex flex-col space-y-4 text-left w-full">
              
              {/* 영화 제목 및 정보 */}
              <div>
                <span className="text-[10px] font-black text-white bg-[#503396] px-3 py-1 rounded-full shadow-sm mb-2 inline-block">
                  분석 완료 매칭작
                </span>
                <h3 className="text-2xl font-black text-zinc-900 mt-1 mb-2 drop-shadow-sm leading-tight">
                  {recommendedMovie.title}
                </h3>
              </div>

              {/* 데이터 기반 추천 이유 & 후기 */}
              <div className="bg-white/50 rounded-xl p-4 border border-white/50 shadow-sm space-y-3">
                
                {/* 1. 추천 데이터 (평점/장르) */}
                <div className="flex items-start gap-2">
                  <span className="text-lg">📊</span>
                  <div>
                    <span className="block text-[11px] font-black text-[#503396]">추천 데이터 분석</span>
                    <span className="text-xs text-zinc-700 font-medium leading-relaxed">
                      {recommendedMovie.reasonData}
                    </span>
                  </div>
                </div>

                <div className="w-full h-px bg-white/60"></div>

                {/* 2. 관람객 후기 (시뮬레이션) */}
                <div className="flex items-start gap-2">
                  <span className="text-lg">💬</span>
                  <div>
                    <span className="block text-[11px] font-black text-[#503396]">비슷한 감정의 관람객 후기</span>
                    <span className="text-xs text-zinc-800 font-black italic">
                      {recommendedMovie.mockReview}
                    </span>
                  </div>
                </div>

              </div>

              {/* 하단 액션 버튼 */}
              <div className="flex gap-3 pt-2">
                <Link 
                  to="/schedule" 
                  className="flex-grow text-center py-3.5 bg-[#503396]/90 hover:bg-[#503396] text-white font-black text-xs rounded-xl transition shadow-md backdrop-blur-md"
                >
                  상영시간표 및 예매하기
                </Link>
                <button 
                  onClick={() => { setSelectedEmotion(null); setRecommendedMovie(null); setInputText(''); }} 
                  className="px-5 py-3.5 bg-white/80 hover:bg-white text-zinc-700 font-black text-xs rounded-xl transition shadow-sm backdrop-blur-md border border-white/60"
                >
                  초기화
                </button>
              </div>
            </div>

          </div>
        )}
      </div>
    </div>
  );
}

export default EmotionRecommendPage;
